            },
            {
              "card": "Ra9f2c23c0275",
              "field": "variables"
            },
            {
              "card": "Ra9f2c23c0275",
              "field": "invalidate"
            },
            {
              "card": "Ra9f2c23c0275",
              "field": "gap"
            }
          ]
        }
      ]
    },
    {
      "title": "从投产到回款，预测需要保留哪些时滞？",
      "paragraphs": [
        {
          "text": "可用产能、利用率和良率决定产出条件，再结合订单形成销量，乘以实现净价得到收入。海外建设之后还有菌种工艺爬坡、客户认证、销售和回款，各笔投入支持的收益年度需要分别登记。",
          "anchors": [
            {
              "card": "R29373d7bc0f1",
              "field": "claim"
            },
            {
              "card": "R29373d7bc0f1",
              "field": "evidence"
            },
            {
              "card": "R29373d7bc0f1",
              "field": "mechanism"
            },
            {
              "card": "R29373d7bc0f1",
              "field": "alternative"
            },
            {
              "card": "R29373d7bc0f1",
              "field": "variables"
            },
            {
              "card": "R29373d7bc0f1",
              "field": "invalidate"
            },
            {
              "card": "R29373d7bc0f1",
              "field": "gap"
            }
          ]
        },
        {
          "text": "分厂、分应用补齐销量净价、糖蜜和能源采购、产能与利用率；将当地币经营变化与汇率换算分开。新厂投产后的首个完整年度是一个回报观察点，同期利润与资本增量则需另外拆出存量业务贡献。",
          "anchors": [
            {
              "card": "R29373d7bc0f1",
              "field": "claim"
